import React, { useState, useEffect, useRef } from 'react';
import { Link } from 'react-router-dom';
import { Map } from 'lucide-react';
import { PhotoProvider, PhotoView } from 'react-photo-view';
import './CityInfo.css';

const CityInfo = ({ language }) => {
  const [isVisible, setIsVisible] = useState(false);
  const sectionRef = useRef(null);
  const publicUrl = process.env.PUBLIC_URL || '';
  const rightBgImage = `${publicUrl}/images/bg-3.jpg`; 

  useEffect(() => {
    const observer = new IntersectionObserver(([entry]) => {
      if (entry.isIntersecting) { setIsVisible(true); observer.disconnect(); }
    }, { threshold: 0.1 });
    if (sectionRef.current) observer.observe(sectionRef.current);
    return () => observer.disconnect();
  }, []);

  const content = {
    RU: {
      leftTitle: 'О Тюмени', leftDesc: 'Здесь самый большой драматический театр в России, термальные источники под открытым небом и набережная в четыре уровня. И это еще не всё...',
      mapBtn: 'Открыть карту', rightTitle: 'Инфо о Тюмени',
      rightSubtitle: 'Это первый русский город в Сибири, основанный в 1586 году. Тогда это был укреплённый острог, а сегодня — современный город с 400-летней историей.',
      quote: '«Тюмень — это не то, что я думал. Она оказалась современной и красивой»'
    },
    EN: {
      leftTitle: 'About Tyumen', leftDesc: 'It has the largest drama theater in Russia, open-air thermal springs, and a four-level embankment. And that’s not all...',
      mapBtn: 'Open Map', rightTitle: 'Info about Tyumen',
      rightSubtitle: 'This is the first Russian city in Siberia, founded in 1586. Then it was a fortified prison, and today it is a modern city with a 400-year history.',
      quote: '"Tyumen is not what I thought. It turned out to be modern and beautiful"'
    }
  };

  const data = content[language];
  const photos = [
    `${publicUrl}/images/bg-1.jpg`, `${publicUrl}/images/bg-2.jpg`,
    `${publicUrl}/images/bg-3.jpg`, `${publicUrl}/images/bg-4.jpg`,
    `${publicUrl}/images/bg-5.jpg`
  ];

  return (
    <section className={`city-info-section ${isVisible ? 'animate-in' : ''}`} ref={sectionRef}>
      <div className="container">
        <div className="ci-interlock-grid" id="tour-cityinfo">
          
          <div className="ci-shape-left">
            <div className="ci-left-top">
              <h3>{data.leftTitle}</h3><p>{data.leftDesc}</p>
              <Link to="/map" className="ci-map-btn"><Map size={18} strokeWidth={2.5} /><span>{data.mapBtn}</span></Link>
            </div>
            <div className="ci-left-bottom">
              <PhotoProvider speed={() => 300}>
                <div className="ci-photos">
                  {photos.map((src, idx) => (
                    <PhotoView key={idx} src={src}>
                      <img src={src} alt={`Тюмень ${idx + 1}`} style={{cursor: 'pointer'}} />
                    </PhotoView>
                  ))}
                </div>
              </PhotoProvider>
            </div>
          </div>

          <div className="ci-shape-right" style={{ '--bg-img': `url(${rightBgImage})` }}>
            <div className="ci-right-top"><div className="ci-seamless-bg"></div><div className="ci-bg-overlay" style={{ opacity: 0.35 }}></div></div>
            <div className="ci-right-bottom"><div className="ci-seamless-bg bottom-bg"></div><div className="ci-bg-overlay" style={{ opacity: 0.35 }}></div>
              <div className="ci-right-content">
                <h3>{data.rightTitle}</h3><p className="ci-right-subtitle">{data.rightSubtitle}</p>
                <div className="ci-quote-box"><p>{data.quote}</p></div>
              </div>
            </div>
          </div>

        </div>
      </div>
    </section>
  );
};

export default CityInfo;